llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Artemisinin, the closest retrieved lactone-containing natural product analogue, was reported to achieve good absolute bioavailability after a single oral dose in malaria patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Artesunate, a structurally related sesquiterpene lactone, showed an absolute oral bioavailability of 61% in Thai patients, providing quantitative evidence that complex lactone natural products can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Retrorsine, another polycyclic natural product lactone, had a predicted absolute oral bioavailability of 44%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Menogaril, a complex polycyclic natural product, had a mean systemic bioavailability of 33.6 ± 10.5% after oral dosing, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Idarubicin had a median oral bioavailability of 29% (range 12–49%) in patients, with the central estimate above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Artemisinin was described as having low and variable oral bioavailability in humans, a qualitative contradictory signal, but no threshold-specific F value below 20% was established.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Limonin, a polycyclic triterpenoid lactone, showed poor bioavailability in humans, a qualitative low signal that is not clearly threshold-specific.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polycyclic diterpene lactone (triptolide-like). Although the retrieved analogues have low Morgan similarity, the quantitative oral bioavailability values that transfer are predominantly above 20% (artesunate 61%, retrorsine 44%, menogaril ~32–34%, idarubicin ~29%). Qualitative 'low/poor' reports for artemisinin, limonin, and 8-PN are not threshold-specific and are outweighed by the quantitative high-F evidence. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the query molecule is available in the evidence set.",
    "All retrieved analogues have low Morgan similarity (<0.18), limiting structural transferability.",
    "Several low-bioavailability records are qualitative and do not report F values relative to the 20% threshold.",
    "Species differences (rat vs human) and dose-dependent absorption may affect the quantitative transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

